package com.bank.fees;

import java.math.BigDecimal;
import java.util.logging.*;

public class FinalInitDemo {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // ---- BROKEN version (uncomment to see the compile error) ----
        // final int x;
        // System.out.println(x);   // error: variable x might not have been initialized

        // ---- CORRECT blank-final version ----
        final int x;      // declared, not yet assigned (blank final)
        x = 20;           // assigned exactly ONCE before any read
        log.info(() -> "x after blank-final assignment = " + x);

        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000.00"));
        FeePolicy policy = new FeePolicy();
        BigDecimal fee = policy.feeFor(rajesh, "SAVINGS");
        log.info(() -> "Fee for " + rajesh.getAccountId() + " = Rs." + fee);
    }
}

