class Account {
    private final String accountId;  // final FIELD assigned in constructor (not at decl)
    private final String holderName;
    private final BigDecimal balance;
    Account(String accountId, String holderName, BigDecimal balance) {
        this.accountId = accountId;   // must be assigned here or compile error
        this.holderName = holderName;
        this.balance = balance;
    }
    String getAccountId() { return accountId; }
    BigDecimal getBalance() { return balance; }
}

// ─── Would be FeePolicy.java in a real project ───
class FeePolicy {
    // Correct use of a blank final: assigned exactly once on EVERY path.
    BigDecimal feeFor(Account account, String type) {
        final BigDecimal fee;              // blank final local
        if ("SAVINGS".equals(type)) {
            fee = new BigDecimal("100.00"); // assigned on this path
        } else {
            fee = new BigDecimal("250.00"); // assigned on this path
        }
        // every path assigned 'fee' exactly once -> now legal to read
        return fee;
    }
}
